swift - <<'SWIFT'
import Foundation
import AppKit

let path = NSHomeDirectory() + "/Library/Preferences/com.apple.Terminal.plist"
guard let data = FileManager.default.contents(atPath: path),
      var plist = try? PropertyListSerialization.propertyList(from: data, format: nil) as? [String: Any],
      var settings = plist["Window Settings"] as? [String: [String: Any]],
      let font = NSFont(name: "MesloLGMNerdFontMono-Regular", size: 12) else {
    fputs("failed to load plist or font\n", stderr)
    exit(1)
}
let archived = try NSKeyedArchiver.archivedData(withRootObject: font, requiringSecureCoding: false)
for name in settings.keys {
    settings[name]?["Font"] = archived
    settings[name]?["FontAntialias"] = true
}
plist["Window Settings"] = settings
let out = try PropertyListSerialization.data(fromPropertyList: plist, format: .xml, options: 0)
try out.write(to: URL(fileURLWithPath: path))
print("Updated Terminal.app profiles:", settings.keys.sorted().joined(separator: ", "))
