swift - <<'SWIFT'
import Foundation
import AppKit
import CoreText

let fontURL = URL(fileURLWithPath: NSHomeDirectory() + "/Library/Fonts/MesloLGMNerdFontMono-Regular.ttf")
guard let descs = CTFontManagerCreateFontDescriptorsFromURL(fontURL as CFURL) as? [CTFontDescriptor],
      let desc = descs.first else { fatalError("font desc") }
let ctFont = CTFontCreateWithFontDescriptor(desc, 12, nil)
let psName = CTFontCopyPostScriptName(ctFont) as String
let nsFont = NSFont(name: psName, size: 12) ?? NSFont(descriptor: NSFontDescriptor(fontAttributes: [.family: "MesloLGM Nerd Font Mono", .size: 12]), size: 12)

let path = NSHomeDirectory() + "/Library/Preferences/com.apple.Terminal.plist"
guard let data = FileManager.default.contents(atPath: path),
      var plist = try? PropertyListSerialization.propertyList(from: data, format: nil) as? [String: Any],
      var settings = plist["Window Settings"] as? [String: [String: Any]],
      let font = nsFont else { fatalError("setup failed") }

let archived = try NSKeyedArchiver.archivedData(withRootObject: font, requiringSecureCoding: false)
for name in settings.keys {
    settings[name]?["Font"] = archived
    settings[name]?["FontAntialias"] = true
}
plist["Window Settings"] = settings
let out = try PropertyListSerialization.data(fromPropertyList: plist, format: .xml, options: 0)
try out.write(to: URL(fileURLWithPath: path))
print("Updated", settings.keys.count, "Terminal.app profiles to", font.fontName, "@12")
SWIFT

